@import "tailwindcss";
@import "uniwind";

@theme {
  --color-background: hsl(77.1 33.3% 95.9%);
  --color-foreground: hsl(95.5 29.7% 14.5%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(95.5 29.7% 14.5%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(95.5 29.7% 14.5%);
  --color-primary: hsl(105.2 42.3% 39.4%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(77.5 32.4% 85.5%);
  --color-secondary-foreground: hsl(95.5 29.7% 14.5%);
  --color-muted: hsl(77.5 32.4% 85.5%);
  --color-muted-foreground: hsl(83.6 13.0% 50.4%);
  --color-accent: hsl(72.6 42.2% 91.2%);
  --color-accent-foreground: hsl(79.1 34.8% 26.5%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(79.3 36.8% 85.1%);
  --color-input: hsl(81.7 31.6% 77.6%);
  --color-ring: hsl(105.2 42.3% 39.4%);
  --radius-lg: 0.5rem;
  --radius-md: calc(0.5rem - 2px);
  --radius-sm: calc(0.5rem - 4px);
}

@layer theme {
  :root {
    @variant light {
  --color-background: hsl(77.1 33.3% 95.9%);
  --color-foreground: hsl(95.5 29.7% 14.5%);
  --color-card: hsl(0 0% 100.0%);
  --color-card-foreground: hsl(95.5 29.7% 14.5%);
  --color-popover: hsl(0 0% 100.0%);
  --color-popover-foreground: hsl(95.5 29.7% 14.5%);
  --color-primary: hsl(105.2 42.3% 39.4%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(77.5 32.4% 85.5%);
  --color-secondary-foreground: hsl(95.5 29.7% 14.5%);
  --color-muted: hsl(77.5 32.4% 85.5%);
  --color-muted-foreground: hsl(83.6 13.0% 50.4%);
  --color-accent: hsl(72.6 42.2% 91.2%);
  --color-accent-foreground: hsl(79.1 34.8% 26.5%);
  --color-destructive: hsl(5.6 63.4% 46.1%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(79.3 36.8% 85.1%);
  --color-input: hsl(81.7 31.6% 77.6%);
  --color-ring: hsl(105.2 42.3% 39.4%);
    }

    @variant dark {
  --color-background: hsl(85.0 40.0% 5.9%);
  --color-foreground: hsl(84.8 38.7% 85.3%);
  --color-card: hsl(87.3 29.7% 14.5%);
  --color-card-foreground: hsl(84.8 38.7% 85.3%);
  --color-popover: hsl(84.0 36.6% 8.0%);
  --color-popover-foreground: hsl(84.8 38.7% 85.3%);
  --color-primary: hsl(101.0 40.2% 50.8%);
  --color-primary-foreground: hsl(0 0% 100.0%);
  --color-secondary: hsl(84.0 35.7% 11.0%);
  --color-secondary-foreground: hsl(84.8 38.7% 85.3%);
  --color-muted: hsl(84.0 35.7% 11.0%);
  --color-muted-foreground: hsl(84.9 18.2% 44.1%);
  --color-accent: hsl(84.0 28.6% 13.7%);
  --color-accent-foreground: hsl(80.3 41.8% 72.4%);
  --color-destructive: hsl(4.6 65.6% 64.7%);
  --color-destructive-foreground: hsl(0 0% 100.0%);
  --color-border: hsl(87.3 29.7% 14.5%);
  --color-input: hsl(90.0 32.1% 22.0%);
  --color-ring: hsl(101.0 40.2% 50.8%);
    }
  }
}
